ALTER TABLE public.company_settings ADD COLUMN claim_incentive_all_jobs boolean NOT NULL DEFAULT false;
DO $$ DECLARE f text; BEGIN f=pg_get_functiondef('public.guard_claim_incentive()'::regprocedure); f=replace(f,'claim_incentive_enabled OR NEW.claim_incentive_cents<>0','claim_incentive_enabled OR NEW.claim_incentive_all_jobs OR NEW.claim_incentive_cents<>0'); f=replace(f,'NEW.claim_incentive_enabled IS DISTINCT FROM OLD.claim_incentive_enabled OR','NEW.claim_incentive_all_jobs IS DISTINCT FROM OLD.claim_incentive_all_jobs OR NEW.claim_incentive_enabled IS DISTINCT FROM OLD.claim_incentive_enabled OR'); f=replace(f,'CASE WHEN claim_incentive_enabled THEN','CASE WHEN claim_incentive_enabled AND (NEW.open_to_claim OR claim_incentive_all_jobs) THEN'); EXECUTE f; END $$;
CREATE FUNCTION public.guard_scheduled_travel_day() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE day date; BEGIN IF auth.uid() IS NOT NULL AND NEW.status='in_transit' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM 'in_transit') AND NEW.job_id IS NOT NULL THEN SELECT scheduled_date INTO day FROM public.jobs WHERE id=NEW.job_id AND company_id=NEW.company_id; IF day IS NOT NULL AND day<>(now() AT TIME ZONE 'Europe/Malta')::date THEN RAISE EXCEPTION 'Travel can only start on the scheduled date'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER scheduled_travel_day BEFORE INSERT OR UPDATE ON public.job_sheets FOR EACH ROW EXECUTE FUNCTION public.guard_scheduled_travel_day();
CREATE FUNCTION public.workspace_thread_can(_kind text,_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.member_is_active(auth.uid()) AND public.company_module_access(public.current_company_id(),'core') AND CASE _kind WHEN 'leave' THEN EXISTS(SELECT 1 FROM public.leave_requests l WHERE l.id=_id AND l.company_id=public.current_company_id() AND (l.user_id=auth.uid() OR (public.is_company_manager() AND public.bell_role_can(l.company_id,public.my_role(),'leave_approvals') AND (public.my_role() IN ('admin','superuser') OR l.consulted_supervisor_id=auth.uid() OR public.has_role(l.user_id,'technician'))))) WHEN 'equipment' THEN public.is_company_manager() AND public.bell_role_can(public.current_company_id(),public.my_role(),'pending_works') AND EXISTS(SELECT 1 FROM public.equipment_problem_reports WHERE id=_id AND company_id=public.current_company_id()) WHEN 'store' THEN public.is_company_manager() AND public.bell_role_can(public.current_company_id(),public.my_role(),'pending_works') AND EXISTS(SELECT 1 FROM public.store_problem_reports WHERE id=_id AND company_id=public.current_company_id()) ELSE false END $$;
REVOKE ALL ON FUNCTION public.workspace_thread_can(text,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.workspace_thread_can(text,uuid) TO authenticated,service_role;
CREATE TABLE public.workspace_thread_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL DEFAULT public.current_company_id(),kind text NOT NULL,record_id uuid NOT NULL,author_id uuid NOT NULL DEFAULT auth.uid(),author_name text NOT NULL DEFAULT '',body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.workspace_thread_messages TO authenticated; GRANT ALL ON public.workspace_thread_messages TO service_role;
ALTER TABLE public.workspace_thread_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY thread_read ON public.workspace_thread_messages FOR SELECT TO authenticated USING(company_id=public.current_company_id() AND public.workspace_thread_can(kind,record_id));
CREATE POLICY thread_write ON public.workspace_thread_messages FOR INSERT TO authenticated WITH CHECK(company_id=public.current_company_id() AND author_id=auth.uid() AND public.workspace_thread_can(kind,record_id));
CREATE INDEX workspace_thread_lookup ON public.workspace_thread_messages(kind,record_id,created_at);
CREATE TABLE public.workspace_thread_alerts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,recipient_id uuid NOT NULL,kind text NOT NULL,record_id uuid NOT NULL,title text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),seen_at timestamptz);
GRANT SELECT,UPDATE(seen_at) ON public.workspace_thread_alerts TO authenticated; GRANT ALL ON public.workspace_thread_alerts TO service_role;
ALTER TABLE public.workspace_thread_alerts ENABLE ROW LEVEL SECURITY;
CREATE POLICY alert_read ON public.workspace_thread_alerts FOR SELECT TO authenticated USING(recipient_id=auth.uid() AND company_id=public.current_company_id() AND public.workspace_thread_can(kind,record_id));
CREATE POLICY alert_seen ON public.workspace_thread_alerts FOR UPDATE TO authenticated USING(recipient_id=auth.uid() AND company_id=public.current_company_id()) WITH CHECK(recipient_id=auth.uid() AND company_id=public.current_company_id());
CREATE FUNCTION public.guard_workspace_message() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.workspace_thread_can(NEW.kind,NEW.record_id) OR NEW.author_id IS DISTINCT FROM auth.uid() OR NEW.company_id IS DISTINCT FROM public.current_company_id() OR length(trim(NEW.body)) NOT BETWEEN 1 AND 4000 THEN RAISE EXCEPTION 'Conversation unavailable or message invalid'; END IF; NEW.body=trim(NEW.body); NEW.created_at=now(); SELECT full_name INTO NEW.author_name FROM public.users WHERE id=auth.uid() AND company_id=NEW.company_id;
INSERT INTO public.workspace_thread_alerts(company_id,recipient_id,kind,record_id,title) SELECT NEW.company_id,r.user_id,NEW.kind,NEW.record_id,CASE WHEN NEW.kind='leave' THEN 'New leave conversation reply' ELSE 'New problem report reply' END FROM public.user_roles r WHERE r.company_id=NEW.company_id AND r.registration_status='active' AND r.user_id<>auth.uid() AND public.member_is_active(r.user_id) AND CASE WHEN NEW.kind='leave' THEN EXISTS(SELECT 1 FROM public.leave_requests l WHERE l.id=NEW.record_id AND (r.user_id=l.user_id OR (public.bell_role_can(r.company_id,r.role,'leave_approvals') AND (r.role IN ('admin','superuser') OR r.user_id=l.consulted_supervisor_id OR r.role='supervisor' AND public.has_role(l.user_id,'technician'))))) ELSE r.role IN ('admin','superuser','supervisor') AND public.bell_role_can(r.company_id,r.role,'pending_works') END; RETURN NEW; END $$;
CREATE TRIGGER workspace_message_guard BEFORE INSERT ON public.workspace_thread_messages FOR EACH ROW EXECUTE FUNCTION public.guard_workspace_message();
CREATE FUNCTION public.notify_leave_decision() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status IS DISTINCT FROM OLD.status AND NEW.status IN ('approved','rejected') THEN INSERT INTO public.workspace_thread_alerts(company_id,recipient_id,kind,record_id,title) VALUES(NEW.company_id,NEW.user_id,'leave',NEW.id,'Leave request '||NEW.status); END IF; RETURN NEW; END $$;
CREATE TRIGGER leave_decision_alert AFTER UPDATE ON public.leave_requests FOR EACH ROW EXECUTE FUNCTION public.notify_leave_decision();
CREATE OR REPLACE FUNCTION public.notify_leave_consultation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.consulted_supervisor_id IS DISTINCT FROM OLD.consulted_supervisor_id AND NEW.consulted_supervisor_id IS NOT NULL THEN INSERT INTO public.workspace_thread_alerts(company_id,recipient_id,kind,record_id,title) VALUES(NEW.company_id,NEW.consulted_supervisor_id,'leave',NEW.id,'Leave operational input requested'); END IF;RETURN NEW;END $$;